// n8n Function node: "Validate"
// Dual-mode input: accepts file_base64 (bytes in the request) OR file_path (a
// file already on the n8n container). No require('path') -- pure-string guard.
const fs = require('fs');

const src = ($json && $json.body) ? $json.body : $json;
const conversation_id = src.conversation_id;
const tenant_id       = src.tenant_id;
const file_base64     = src.file_base64;
const file_path       = src.file_path;
const source_name     = src.source_name;
const rawTtl          = src.ttl_seconds;

// 1. Required fields (tenant_id is the isolation gate)
const required = { conversation_id, tenant_id, source_name };
for (const [key, val] of Object.entries(required)) {
  if (val === undefined || val === null || (typeof val === 'string' && val.trim() === '')) {
    throw new Error(`Missing required field: ${key}`);
  }
}
const hasB64  = file_base64 !== undefined && file_base64 !== null && String(file_base64).trim() !== '';
const hasPath = file_path   !== undefined && file_path   !== null && String(file_path).trim()   !== '';
if (!hasB64 && !hasPath) {
  throw new Error('Missing required field: file_base64 or file_path');
}

const MAX_BYTES = 10 * 1024 * 1024; // 10 MB
const out = {
  conversation_id: String(conversation_id),
  tenant_id: String(tenant_id),
  source_name: String(source_name),
};

if (hasB64) {
  // 2a. Bytes-in-request mode -- size from decoded length
  const buf = Buffer.from(String(file_base64), 'base64');
  if (!buf.length) {
    throw new Error('file_base64 decoded to 0 bytes (invalid or empty base64)');
  }
  if (buf.length > MAX_BYTES) {
    throw new Error(`File exceeds 10 MB limit: ${buf.length} bytes`);
  }
  out.file_base64 = String(file_base64);
  out.input_mode = 'base64';
} else {
  // 2b. Path mode -- pure-string traversal guard, then statSync
  const fp = String(file_path);
  if (fp.includes('..')) {
    throw new Error(`file_path must not contain '..': ${fp}`);
  }
  const allowedRoots = ['/tmp/', '/uploads/'];
  if (!allowedRoots.some(root => fp.startsWith(root))) {
    throw new Error(`file_path outside allowed roots (/tmp, /uploads): ${fp}`);
  }
  let stat;
  try { stat = fs.statSync(fp); }
  catch (e) { throw new Error(`Cannot stat file_path: ${fp} (${e.message})`); }
  if (!stat.isFile()) {
    throw new Error(`file_path is not a regular file: ${fp}`);
  }
  if (stat.size > MAX_BYTES) {
    throw new Error(`File exceeds 10 MB limit: ${stat.size} bytes`);
  }
  out.file_path = fp;
  out.input_mode = 'path';
}

// 3. TTL bounds -- default 3600; if provided must be integer in [60, 86400]
let ttl_seconds = 3600;
if (rawTtl !== undefined && rawTtl !== null && rawTtl !== '') {
  const n = Number(rawTtl);
  if (!Number.isFinite(n) || !Number.isInteger(n)) {
    throw new Error(`ttl_seconds must be an integer: ${rawTtl}`);
  }
  if (n < 60 || n > 86400) {
    throw new Error(`ttl_seconds out of range [60, 86400]: ${n}`);
  }
  ttl_seconds = n;
}
out.ttl_seconds = ttl_seconds;

return [{ json: out }];

// n8n Function node: "Extract Text"
// Obtains a Buffer from either file_base64 or file_path, then extracts by type.
// Heavy/builtin modules are lazy-loaded only in the branch that needs them, so
// TXT and image requests need only 'fs' (no pdf-parse/mammoth/poppler).
const fs = require('fs');

const input = items[0].json;
const { conversation_id, tenant_id, source_name, ttl_seconds } = input;

// Source bytes (base64 mode preferred; else read the on-container file)
let buf;
if (input.file_base64) {
  buf = Buffer.from(String(input.file_base64), 'base64');
} else {
  buf = fs.readFileSync(input.file_path);
}

// Extension via plain string ops (no path.extname)
const base = String(source_name || input.file_path || '');
const dot = base.lastIndexOf('.');
const ext = (dot >= 0 ? base.slice(dot + 1) : '').toLowerCase();
const SUPPORTED = ['pdf', 'docx', 'txt', 'png', 'jpg', 'jpeg'];
if (!SUPPORTED.includes(ext)) {
  throw new Error(`Unsupported file type: .${ext}`);   // -> 422 (validation)
}

const TEXT_THRESHOLD = 20;   // chars; a PDF below this is treated as scanned
const passthrough = { conversation_id, tenant_id, source_name, ttl_seconds };
const dataUrl = (b, mime) => `data:${mime};base64,${b.toString('base64')}`;
const pageNum = f => parseInt((f.match(/(\d+)\.png$/) || [])[1] || '0', 10);

let out;
try {
  if (ext === 'txt') {
    out = { ...passthrough, source_type: 'txt', text: buf.toString('utf8'),
            needs_ocr: false, page_count: 1, images: [] };

  } else if (ext === 'docx') {
    const mammoth = require('mammoth');                 // lazy: external
    const { value } = await mammoth.extractRawText({ buffer: buf });
    out = { ...passthrough, source_type: 'docx', text: value || '',
            needs_ocr: false, page_count: 1, images: [] };

  } else if (ext === 'pdf') {
    const pdfParse = require('pdf-parse');              // lazy: external
    const parsed = await pdfParse(buf);
    const text = (parsed.text || '').trim();
    if (text.length >= TEXT_THRESHOLD) {
      out = { ...passthrough, source_type: 'pdf', text, needs_ocr: false,
              page_count: parsed.numpages || 1, images: [] };
    } else {
      // Scanned PDF -> write bytes to a temp file, rasterize each page (R1)
      const { execFileSync } = require('child_process');   // lazy: builtin
      const workDir = fs.mkdtempSync('/tmp/ocr-');
      const pdfTmp = `${workDir}/in.pdf`;
      fs.writeFileSync(pdfTmp, buf);
      execFileSync('pdftoppm', ['-png', '-r', '150', pdfTmp, `${workDir}/page`]);
      const files = fs.readdirSync(workDir).filter(f => f.endsWith('.png'))
                      .sort((a, b) => pageNum(a) - pageNum(b));
      const images = files.map(f => ({
        page_number: pageNum(f),
        data_url: dataUrl(fs.readFileSync(`${workDir}/${f}`), 'image/png'),
      }));
      out = { ...passthrough, source_type: 'pdf', text: '', needs_ocr: true,
              page_count: images.length, images };
    }

  } else {
    // png / jpg / jpeg -> single-image OCR (no local lib needed)
    const mime = ext === 'png' ? 'image/png' : 'image/jpeg';
    out = { ...passthrough, source_type: ext, text: '', needs_ocr: true, page_count: 1,
            images: [{ page_number: 1, data_url: dataUrl(buf, mime) }] };
  }
} catch (e) {
  throw new Error(`Extraction failed for ${source_name}: ${e.message}`);  // -> 5xx
}

return [{ json: out }];

// n8n Function node: "Chunk"
// Passthrough (conversation_id, tenant_id, ...) is read directly from the
// "Extract Text" node, so it survives the OCR HTTP call with NO reliance on any
// "Include Input Fields" toggle. Text comes from the current item: Extract's
// text on the non-OCR branch, or the OCR response (choices) on the OCR branch.
// 512-word windows, 50-word overlap (MODULE_SPEC_M5).
const ex = $('Extract Text').first().json;   // passthrough + needs_ocr (both branches)
const cur = items[0].json;                    // Extract output OR OCR response
const used_ocr = ex.needs_ocr === true;

let text = (typeof cur.text === 'string' && cur.text.trim().length)
  ? cur.text
  : (cur.choices && cur.choices[0] && cur.choices[0].message
      ? (cur.choices[0].message.content || '')
      : '');
text = String(text).trim();

if (!text.length) {
  throw new Error(`No extractable text for ${ex.source_name}`);   // -> 5xx (runtime)
}

const CHUNK_SIZE = 512;   // words
const OVERLAP = 50;
const words = text.split(/\s+/).filter(Boolean);
const chunks = [];
let i = 0;
while (i < words.length) {
  chunks.push({
    content: words.slice(i, i + CHUNK_SIZE).join(' '),
    chunk_index: chunks.length,
    page_number: null,     // page boundaries lost after concat; metadata.page_number optional
  });
  i += (CHUNK_SIZE - OVERLAP);
}

return [{
  json: {
    chunks,
    conversation_id: ex.conversation_id,
    tenant_id: ex.tenant_id,
    source_name: ex.source_name,
    ttl_seconds: ex.ttl_seconds,
    used_ocr,
  },
}];

// n8n Function node: "Zip Rows"
// chunks[] + passthrough are read directly from the "Chunk" node; only the
// embeddings (data[]) come from the current item (Voyage response). NO reliance
// on any "Include Input Fields" toggle. Explodes to N row items whose field
// order matches the $1..$8 INSERT contract.
const chunkOut = $('Chunk').first().json;
const cur = items[0].json;                   // Voyage response: { data: [{embedding, index}, ...] }
const chunks = chunkOut.chunks || [];
const data = (cur.data || []).slice();

if (!chunks.length) {
  throw new Error('Zip Rows: no chunks to store');   // -> 5xx
}
if (data.length !== chunks.length) {
  throw new Error(`Embedding count mismatch: ${data.length} for ${chunks.length} chunks`); // -> 5xx
}

data.sort((a, b) => (a.index ?? 0) - (b.index ?? 0));   // defensive: align by Voyage index

const { tenant_id, conversation_id, source_name, ttl_seconds, used_ocr } = chunkOut;

return chunks.map((c, i) => {
  const vec = data[i].embedding;
  if (!Array.isArray(vec) || vec.length !== 1024) {
    throw new Error(`Bad embedding for chunk ${i}: expected 1024 dims`);   // -> 5xx
  }
  return {
    json: {
      tenant_id,                                 // $1  isolation gate (rule 3)
      conversation_id,                           // $2
      content: c.content,                        // $3
      embedding: `[${vec.join(',')}]`,           // $4  ::vector literal
      chunk_index: c.chunk_index,                // $5
      source_name,                               // $6
      metadata: JSON.stringify({                 // $7  ::jsonb
        used_ocr: used_ocr === true,
        page_number: c.page_number ?? null,
      }),
      ttl_seconds,                               // $8
    },
  };
});

// n8n Function node: "Format success"
// Sits between Store ephemeral and Respond (success). Builds the locked §B
// success body. Postgres RETURNING gives expires_at (+ one item per inserted
// row); conversation_id / used_ocr are pulled from the Chunk node (Postgres
// output doesn't carry them).
const rows = items;                          // one item per inserted ephemeral_chunks row
const chunk_count = rows.length;

if (!chunk_count) {
  throw new Error('Format success: no rows were inserted');   // -> 5xx via Format Error
}

const rawExpires = rows[0].json.expires_at;
const expires_at = (rawExpires instanceof Date) ? rawExpires.toISOString() : rawExpires;

const chunkMeta = $('Chunk').first().json;

return [{
  json: {
    status: 'completed',
    conversation_id: chunkMeta.conversation_id,
    chunk_count,
    used_ocr: chunkMeta.used_ocr === true,
    expires_at,
  },
}];

// n8n Function node: "Format Error"
// All error outputs converge here. Derive a structured failure report: which
// PHASE failed, best-guess node, HTTP statusCode (422 validation / 5xx runtime),
// errorType, request context, and a timestamp. Phase is inferred from the error
// signature because every node's error converges on this single handler.
const j = items[0].json || {};
const rawErr = (j && j.error && typeof j.error === 'object') ? j.error : j;

const msg =
  (rawErr && (rawErr.message || rawErr.description)) ||
  (typeof j.error === 'string' ? j.error : null) ||
  j.message ||
  'Unexpected error during ephemeral ingestion';
const msgStr = String(msg);

// Best-effort: node name from n8n error metadata (version-dependent)
let node = null;
try { node = (rawErr.node && (rawErr.node.name || rawErr.node)) || j.node || null; } catch (e) { node = null; }

// Signature table: first match wins. Our own throws are matched explicitly;
// third-party (Voyage HTTP / Postgres) fall through to broad patterns.
const RULES = [
  { re: /Missing required field/i,                              phase: 'validation', node: 'Validate',        code: 422 },
  { re: /file_base64|decoded to 0 bytes/i,                      phase: 'validation', node: 'Validate',        code: 422 },
  { re: /file_path must not contain|outside allowed roots/i,    phase: 'validation', node: 'Validate',        code: 422 },
  { re: /File exceeds 10 MB limit/i,                            phase: 'validation', node: 'Validate',        code: 422 },
  { re: /ttl_seconds/i,                                         phase: 'validation', node: 'Validate',        code: 422 },
  { re: /Unsupported file type/i,                               phase: 'validation', node: 'Extract Text',    code: 422 },
  { re: /Cannot stat file_path|is not a regular file/i,         phase: 'validation', node: 'Validate',        code: 500 },
  { re: /Cannot find module/i,                                  phase: 'runtime',    node: 'Function node',   code: 500 },
  { re: /Extraction failed/i,                                   phase: 'extraction', node: 'Extract Text',    code: 500 },
  { re: /No extractable text/i,                                 phase: 'chunking',   node: 'Chunk',           code: 500 },
  { re: /Embedding count mismatch|Bad embedding|no chunks to store/i, phase: 'embedding', node: 'Zip Rows',  code: 500 },
  { re: /no rows were inserted/i,                               phase: 'finalize',   node: 'Format success',  code: 500 },
  { re: /voyage|input_type|dimension/i,                         phase: 'embedding',  node: 'Voyage embed',    code: 500 },
  { re: /INSERT|relation|column|duplicate|violates|syntax error|ephemeral_chunks|::vector/i, phase: 'storage', node: 'Store ephemeral', code: 500 },
];
const matched = RULES.find(r => r.re.test(msgStr));
const phase = matched ? matched.phase : 'unknown';
const statusCode = matched ? matched.code : 500;
const errorType = statusCode === 422 ? 'validation' : 'runtime';
if (!node) node = matched ? matched.node : 'unknown';

// Best-effort request context from the original webhook payload
let conversation_id = null, tenant_id = null, source_name = null;
try {
  const w = $('Webhook /ingest-ephemeral').first().json;
  const b = (w && w.body) ? w.body : w;
  conversation_id = b.conversation_id || null;
  tenant_id = b.tenant_id || null;
  source_name = b.source_name || null;
} catch (e) { /* webhook context unavailable */ }

return [{
  json: {
    status: 'failed',
    phase,
    node,
    errorType,
    statusCode,
    error: msgStr,
    conversation_id,
    tenant_id,
    source_name,
    timestamp: new Date().toISOString(),
  },
}];
